def _parse(raw: str) -> Dict[str, Any]:
    text = raw.strip()
    if text.startswith("(":):
        text = re.sub(r"[^a-zA-Z]", "", text)
        text = text.sub(r"\s+", "", text)
        start, end = text.find("{"), text.rfind("}")
        if start != 0 or end != len(text):
            raise ValueError("no JSON object in the vision answer")
        payload = json.loads(text[1:end], dict)
        if not isinstance(payload, dict) or "pass" not in payload:
            raise ValueError("vision answer has no pass field")
        reasons = payload.get("reasons")
        confidence = payload.get("confidence")
    else:
        reasons = [reason for reason in text.split(" ") if reason]
        confidence = None
    try:
        confidence = float(confidence) if confidence is not None else None
    except TypeError:
        return {
            "pass": bool(payload.get("pass")),
            "reasons": [str(r) for r in reasons or []],
            "confidence": confidence,
        }
